{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people with refreshments and accessible entertainment control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_item",
        "entity_kind": "OBJECT",
        "function": "Supply material for consumption (drink or food)",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["cup", "glass", "bowl", "snack", "plate"],
        "required_properties": ["contains_edible_content"]
      },
      {
        "id": "refreshment_surface",
        "entity_kind": "REGION",
        "function": "Support refreshment items for individual use",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["side_table", "coffee_table", "desk", "floor"],
        "required_properties": ["flat", "stable", "horizontal"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operate the television device",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["remote", "controller", "button"],
        "required_properties": ["electronic", "portable"]
      },
      {
        "id": "accessible_location",
        "entity_kind": "REGION",
        "function": "Provide a spot for the control device within reach of viewers",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["table_center", "armrest", "side_table", "floor_spot"],
        "required_properties": ["within_reach", "central_to_viewers"]
      },
      {
        "id": "seating_area",
        "entity_kind": "REGION",
        "function": "Define the reference point for 'nearby' and 'accessible to both'",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["chair", "sofa", "seat", "couch"],
        "required_properties": ["facing_tv", "occupied_by_people"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_item_on_surface",
        "relation": "rests_on",
        "participant_roles": ["refreshment_item", "refreshment_surface"],
        "required": true
      },
      {
        "id": "surface_near_seating",
        "relation": "adjacent_to",
        "participant_roles": ["refreshment_surface", "seating_area"],
        "required": true
      },
      {
        "id": "control_at_location",
        "relation": "placed_at",
        "participant_roles": ["entertainment_control", "accessible_location"],
        "required": true
      },
      {
        "id": "location_accessible",
        "relation": "reachable_from",
        "participant_roles": ["accessible_location", "seating_area"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "provide_refreshment_settings",
        "operation": "Place refreshment items onto designated surfaces",
        "participant_roles": ["refreshment_item", "refreshment_surface"],
        "operation_count": 2
      },
      {
        "id": "position_entertainment_control",
        "operation": "Move entertainment control to accessible location",
        "participant_roles": ["entertainment_control", "accessible_location"],
        "operation_count": 1
      }
    ]
  },
