        {"label": "desk", "visual_description": "Large wooden desk in foreground"}
      ],
      "entertainment_control": [
        {"label": "remote", "visual_description": "Black remote on desk"}
      ],
      "accessible_location": [],
      "seating_area": [
        {"label": "left_chair", "visual_description": "Armchair with black cushion"},
        {"label": "right_chair", "visual_description": "Armchair with black cushion"}
